begin;
do $$
declare actor uuid; scanner uuid; finance uuid; item uuid; receipt jsonb; result jsonb; original jsonb; qr text; assignment text;
 req uuid:=gen_random_uuid(); scan_req uuid:=gen_random_uuid(); today date:=(clock_timestamp() at time zone 'America/Chicago')::date;
 test_customer text:='V2-ROLLBACK-'||gen_random_uuid();
 oid text; wid text; jid text; test_person text:='V2-TEST-'||gen_random_uuid(); existing_count integer; payroll jsonb;
begin
 select id into strict actor from public.staff_profiles where active and role='admin' limit 1;
 select id into strict scanner from public.staff_profiles where active and role='box_scanner' limit 1;
 select id into strict finance from public.staff_profiles where active and role='accounts' limit 1;
 select count(*) into existing_count from public.orders where total_billable_units is null;
 insert into public.customers(id,name) values(test_customer,'V2 rollback client '||test_customer);
 insert into public.customer_items(customer_id,code,name,rate,unit,pieces_per_unit) values(test_customer,'V2-'||gen_random_uuid(),'V2 rollback item',2.5,'Box',500) returning id into item;
 perform set_config('request.jwt.claim.sub',actor::text,true);
 receipt:=public.app_plan_billable_order(test_customer,item,100,10,today,req);
 oid:=receipt->>'orderId';wid:=receipt->>'workId';jid:=receipt->>'jobId';
 if receipt->>'totalBillableUnits'<>'100' or receipt->>'billableUnitsPerScan'<>'10' then raise exception 'Unit inputs were not preserved';end if;
 result:=public.app_plan_billable_order(test_customer,item,100,10,today,req);
 if result->>'duplicate'<>'true' or result->>'orderId'<>oid then raise exception 'Planning retry created another order';end if;
 begin perform public.app_plan_billable_order(test_customer,item,100,20,today,req);raise exception 'Reused request accepted changed units';exception when raise_exception then if sqlerrm='Reused request accepted changed units' then raise;end if;end;
 begin perform public.app_plan_billable_order(test_customer,item,10,20,today,gen_random_uuid());raise exception 'Invalid scan size accepted';exception when raise_exception then if sqlerrm='Invalid scan size accepted' then raise;end if;end;
 insert into public.people(id,name,kind) values(test_person,'V2 rollback individual','individual');
 result:=public.app_individual_qr_cards(array[test_person],true);qr:=result->0->>'code';
 result:=public.app_scan_and_assign((receipt->>'approvalId')::uuid,qr);
 select id into strict assignment from public.dumping_assignments where person_id=test_person and sub_job_id=jid;
 update public.dumping_assignments set last_scan_at=clock_timestamp()-interval '1 hour',scan_assign_ready_at=clock_timestamp()-interval '1 hour' where id=assignment;
 perform set_config('request.jwt.claim.sub',scanner::text,true);
 original:=public.app_scan_billable_units(qr,assignment,scan_req,10,10);
 if original->>'billableUnits'<>'10' then raise exception 'One scan did not credit ten units';end if;
 result:=public.app_scan_billable_units(qr,assignment,scan_req,20,10);
 if result->>'duplicate'<>'true' or result->>'billableUnits'<>'10' then raise exception 'Retry counted twice or changed receipt';end if;
 begin perform public.app_scan_billable_units(qr,assignment,gen_random_uuid(),20,10);raise exception 'Cooldown was ignored';exception when raise_exception then if sqlerrm not like 'Too soon%' then raise;end if;end;
 update public.dumping_assignments set last_scan_at=clock_timestamp()-interval '1 hour' where id=assignment;
 result:=public.app_scan_billable_units(qr,assignment,gen_random_uuid(),20,10);
 if result->>'billableUnits'<>'20' then raise exception 'Double scan did not credit twenty units';end if;
 if (select billable_units_completed from public.sub_jobs where id=jid)<>30 then raise exception 'Billable progress is wrong';end if;
 if (select total_billable_units from public.orders where id=oid)<>100 then raise exception 'Physical pieces per unit changed the unit total';end if;
 perform set_config('request.jwt.claim.sub',actor::text,true);
 perform public.app_save_billable_scan_settings(wid,0,15);
 if (select billable_units from public.dumping_completions where id=scan_req)<>10 then raise exception 'Settings rewrote historical units';end if;
 update public.orders set data=data||'{"catalogRate":9}' where id=oid;
 perform set_config('request.jwt.claim.sub',scanner::text,true);
 begin perform public.app_scan_billable_units(qr,assignment,gen_random_uuid(),10,10);raise exception 'Stale load accepted';exception when sqlstate 'PT409' then null;end;
 result:=public.app_scan_billable_units(qr,assignment,gen_random_uuid(),15,15);
 if result->>'billableUnits'<>'15' then raise exception 'New units per scan not applied';end if;
 if (select billing_rate_snapshot from public.dumping_completions where id=scan_req)<>2.5 then raise exception 'Historical rate changed';end if;
 perform set_config('request.jwt.claim.sub',actor::text,true);
 result:=manufacturing_private.read_order(oid);
 if result->>'billableUnitsCompleted'<>'45' then raise exception 'Order progress projection failed';end if;
 result:=public.app_individual_timesheet(test_person,date_trunc('week',today)::date);
 if (select sum((e->>'billableUnits')::integer) from jsonb_array_elements(result->'entries') e)<>45 then raise exception 'Timesheet missed units';end if;
 -- Single-use QR completion also captures units and rates exactly once.
 insert into public.people(id,name,kind) values(test_person||'-BOX','V2 box individual','individual');
 perform public.app_create_box(oid,wid,jsonb_build_object('id','V2-BOX-'||substr(replace(gen_random_uuid()::text,'-',''),1,16),'jobId',jid,'personId',test_person||'-BOX','quantity',20,'date',today));
 perform set_config('request.jwt.claim.sub',scanner::text,true);
 select id into assignment from public.boxes where person_id=test_person||'-BOX';
 perform public.app_complete_box(assignment,20);
 if (select billable_units from public.production_records where box_id=assignment)<>20 then raise exception 'Single-use units missing';end if;
 if (select billable_units_completed from public.sub_jobs where id=jid)<>65 then raise exception 'Single-use progress is wrong';end if;
 begin perform public.app_complete_box(assignment,20);raise exception 'Single-use completion counted twice';exception when raise_exception then if sqlerrm='Single-use completion counted twice' then raise;end if;end;
 perform set_config('request.jwt.claim.sub',actor::text,true);
 result:=public.app_configuration_history('scans',today,today,oid,0);
 if (result->>'total')::integer<>4 then raise exception 'History did not include unit scans';end if;
 perform set_config('request.jwt.claim.sub',finance::text,true);
 result:=public.app_billable_unit_report(today,today,0);
 if not exists(select 1 from jsonb_array_elements(result->'rows') e where e->>'order_id'=oid and e->>'units'='45' and (e->>'client_payment')::numeric=210 and (e->>'individual_pay')::numeric=210) then raise exception 'Billing or pay used physical pieces or current rates: %',result;end if;
 payroll:=public.app_accounts_payroll_report(date_trunc('week',today)::date);
 if not exists(select 1 from jsonb_array_elements(payroll) e where e->>'id'=test_person and (e->>'week1WsPay')::numeric=210) then raise exception 'Payroll did not use saved unit rates: %',payroll;end if;
 perform set_config('request.jwt.claim.sub',scanner::text,true);
 begin perform public.app_billable_unit_report(today,today,0);raise exception 'Scanner read finance';exception when insufficient_privilege then null;end;
 begin perform public.app_plan_billable_order(test_customer,item,100,10,today,gen_random_uuid());raise exception 'Scanner planned work';exception when insufficient_privilege then null;end;
 if exists(select 1 from public.orders where total_billable_units is null and id=oid) or (select count(*) from public.orders where total_billable_units is null)<>existing_count then raise exception 'Legacy orders changed';end if;
 if has_function_privilege('anon','public.app_plan_billable_order(text,uuid,integer,integer,date,uuid)','execute') then raise exception 'Anonymous planning exposed';end if;
end $$;
rollback;
